    result = runner.run(["git", "log", "--format=%s", "origin/main..HEAD"], cwd=cwd)
    if result.returncode != 0:
        return ""
    for line in result.stdout.splitlines():
        if _BUMP_SUBJECT_RE.fullmatch(line):
